#include <bits/stdc++.h>using namespace std;#define int long longint n,T; void O_o(){	cin >> n;	vector<int> a(n + 1);	for(int i=1;i<=n;i++){		cin >> a[i];	}	vector<int> b;	for(int i=1;i<=n;i++){		int t;cin >> t;		b.push_back(a[i] + t);		b.push_back(a[i] - t);	}	int x = *max_element(b.begin(),b.end()) + *min_element(b.begin(),b.end());	cout << (x >> 1);	if(x & 1){		cout << ".5";	}	cout << '\n';} signed main(){	ios::sync_with_stdio(false);	cin.tie(nullptr);cout.tie(nullptr);	cin >> T;	while(T--)O_o();	return 0;}